INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter27-bhoodan-movement', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter27-bhoodan-movement-p1", "partName": "Bhoodan Movement — Background and Origins of the Padayatra", "bodyMd": "India''s land problem could be addressed through three approaches: **violence**, **legislation**, and **donation (dāna)**. Communists in India, and particularly in Telangana, pursued the path of violence for some time but failed to achieve a lasting solution through it. The government, for its part, followed the legislative route — enacting laws for land ceiling and redistribution — but implementation of such laws in full has always been a slow process, and legislation alone could not fully resolve the problem.\n\nWhat was needed alongside legal reform was for landowning communities to voluntarily understand their social responsibility and donate land out of genuine goodwill. It was **Vinobha Bhave** who conceived and led this third path — the Bhoodan (land-gift) movement.\n\nThe idea that the land problem could be solved through Bhoodan came to Vinobha suddenly. In **March 1951**, he was invited to attend the Sarvodaya Sammelan being held at **Shivarampalli**, near Hyderabad. He walked **300 miles** from his ashram to reach Hyderabad for this gathering.\n\nDuring this visit, he learned that communists in the Telangana region were resorting to violence and that the rural population lived in constant fear because of it. He resolved to spread a message of love and peace across the region. It was in the context of this visit that the historic Bhoodan movement began in Telangana.\n\n### Launch of the Tour\n\n*   **April 16, 1951 (Sriramanavami)** — Vinobha Bhave announced that he intended to tour the Telangana region as part of his message.\n*   The journey began at **5 a.m.**, with Vinobha''s party covering **10 miles** on foot from Hyderabad city to reach **Hayathnagar**.\n*   Prominent figures who accompanied him included **Dr. G. S. Melkote** and **Dr. Marri Chenna Reddy**, among others.\n*   **April 18, 1951** — As planned, Vinobha Bhave''s party set out from **Batasingaram**. The route ahead passed through hilly, forested terrain, where there was a risk of ambush by dacoits at any point. Vinobha Bhave, however, set out without regard for any such danger, and the party reached **Pochampalli** safely.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter27-bhoodan-movement-p2", "partName": "Pochampalli, the Continuing Yatra, and National Recognition", "bodyMd": "Vinobha Bhave, along with his followers, walked **10–12 miles** each morning, halted in a village, and addressed public meetings there with a message of peace. He visited the huts of Harijans, inquired after their welfare, and looked into their needs.\n\nAfter reaching **Pochampalli village** in **Nalgonda district**, on **April 18**, two Harijans approached him and explained that **forty families** in Pochampalli had no land of their own, and they had no land in the village either; they requested that some land be given to them.\n\nThe local **Deshmukh, V. Ramachandra Reddy**, on hearing this, offered to give **100 acres** from his own land. Vinobha Bhave, addressing the Harijans, said that if they were to accept it, the land should be cultivated under a cooperative system.\n\nThat evening, at the public meeting held at **6 p.m.**, following prayers, Vinobha Bhave announced that the Harijans had asked landlord Ramachandra Reddy for 100 acres, and declared that if even one landlord were to honor such a promise, it could set in motion a great undertaking (_mahattara karyam_) in India. **The Bhoodan Yajna began from that day.**\n\n### Continuation of the Yatra\n\nVinobhaji''s tour proceeded through the **Nalgonda, Devarakonda, and Miryalaguda taluks** and on to **Suryapet**. Communists did not obstruct him anywhere along the way. Vinobhaji sought land donations at every stop, and donors came forward; on some days, as much as **200 acres** of land was donated in a single day.\n\n### National Recognition\n\nVinobha''s Telangana tour proved highly fruitful, and Prime Minister **Jawaharlal Nehru** announced this in Parliament. Nehru''s remark was that, instead of deploying **50,000 troops** to maintain peace and security in Telangana, one selfless individual — Vinobha — was accomplishing that very task on his own.\n\nThis announcement drew the eyes of the world to Vinobha''s padayatra. Whether or how much Vinobha''s message actually curbed acts of violence remained uncertain, but it drew ordinary people to him in large numbers.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter27-bhoodan-movement-p3", "partName": "The 1955 Visit and Palamuru District", "bodyMd": "In **1955**, Vinobha Bhave visited Hyderabad and, at the request that he visit **Palamuru (Mahbubnagar) district**, went there.\n\n**Palleria Hanumantha Rao** offered **50,000 acres** for the Bhoodan movement, declaring that Palamuru would lead the way in this effort. This offer was accepted by all without hesitation. Vinobha toured the entire district, collecting land for the Bhoodan movement from landlords in the **Kalwakurthy, Kollapur, and Nagarkurnool** taluks.\n\n### Madhavarao Palle Village\n\nVinobha Bhave arranged for the donation of **Madhavarao Palle village** in Kollapur taluk. This same village later became the site of the inauguration of **Vanaparthi Polytechnic College**, an event attended by the then Prime Minister, Jawaharlal Nehru — a fact still recalled as a notable historical memory of the region.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter27-bhoodan-movement-p4", "partName": "Vinobha''s Philosophy and Government Recognition of Donated Lands", "bodyMd": "Vinobha held that in a free, democratic nation, problems ought to be resolved harmoniously. He maintained that a non-violent movement against violence should proceed among the people themselves, within the framework of democracy.\n\nIn the context of this tour, the government gave legal standing to the lands received through Bhoodan in Telangana. At that time, **Burgula Ramakrishna Rao** was serving as **Revenue Minister** in **M. K. Vellodi''s** cabinet. He promptly introduced the **Bhoodan Special Rules**, which proved of great use in systematically regularizing the lands that had been received as donations.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter27-bhoodan-movement';
